namespace sv_6b07da2075794190931c4dd397977f61.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@namespace sv_6b07da2075794190931c4dd397977f61.Components.Pages.Settings

<nav class="settings-sidebar">
    <ul class="settings-nav">
        @foreach (var section in Sections)
        {
            <li class="settings-nav-item @(section.Key == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionChanged.InvokeAsync(section.Key)">
                <span class="settings-nav-icon">@section.Icon</span>
                <span class="settings-nav-label">@section.Label</span>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "profile";
    [Parameter] public EventCallback<string> OnSectionChanged { get; set; }

    private record SectionInfo(string Key, string Label, string Icon);

    private static readonly SectionInfo[] Sections =
    [
        new("profile", "Profile", "👤"),
        new("notifications", "Notifications", "🔔"),
        new("security", "Security", "🔒"),
        new("appearance", "Appearance", "🎨")
    ];
}

@namespace sv_6b07da2075794190931c4dd397977f61.Components.Pages.Settings
@using sv_6b07da2075794190931c4dd397977f61.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Profile Settings</h2>

    @if (isLoading)
    {
        <p class="loading-text">Loading profile...</p>
    }
    else
    {
        <div class="profile-form">
            <div class="avatar-preview">
                <img src="@avatarUrl" alt="Avatar" class="avatar-image" />
                <span class="avatar-url-label">@avatarUrl</span>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" class="form-control" @bind="displayName" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" class="form-control" @bind="email" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" class="form-control" rows="4" @bind="bio"></textarea>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveAsync">Save Changes</button>
                <button class="btn btn-secondary" @onclick="DiscardChanges">Discard Changes</button>
            </div>

            @if (!string.IsNullOrEmpty(statusMessage))
            {
                <div class="alert @(isError ? "alert-danger" : "alert-success") mt-3">@statusMessage</div>
            }
        </div>
    }
</div>

@code {
    private string displayName = "";
    private string email = "";
    private string avatarUrl = "";
    private string bio = "";
    private bool isLoading = true;
    private string statusMessage = "";
    private bool isError;

    private UserProfile? savedProfile;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfileAsync();
    }

    private async Task LoadProfileAsync()
    {
        isLoading = true;
        savedProfile = await SettingsService.GetProfileAsync();
        ApplyProfile(savedProfile);
        isLoading = false;
    }

    private void ApplyProfile(UserProfile profile)
    {
        displayName = profile.DisplayName;
        email = profile.Email;
        avatarUrl = profile.AvatarUrl;
        bio = profile.Bio;
    }

    private async Task SaveAsync()
    {
        try
        {
            var profile = new UserProfile(displayName, email, avatarUrl, bio);
            await SettingsService.SaveProfileAsync(profile);
            savedProfile = profile;
            statusMessage = "Profile saved successfully!";
            isError = false;
        }
        catch (Exception ex)
        {
            statusMessage = $"Error saving profile: {ex.Message}";
            isError = true;
        }
    }

    private void DiscardChanges()
    {
        if (savedProfile is not null)
        {
            ApplyProfile(savedProfile);
            statusMessage = "";
        }
    }
}

@namespace sv_6b07da2075794190931c4dd397977f61.Components.Pages.Settings
@using sv_6b07da2075794190931c4dd397977f61.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Notification Preferences</h2>

    @if (isLoading)
    {
        <p class="loading-text">Loading preferences...</p>
    }
    else
    {
        <div class="notification-form">
            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="emailNotifications" />
                    <span>Email Notifications</span>
                </label>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="pushNotifications" />
                    <span>Push Notifications</span>
                </label>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="weeklyDigest" />
                    <span>Weekly Digest</span>
                </label>
            </div>

            <h3 class="mt-4">Muted Channels</h3>
            <div class="channel-list">
                @foreach (var channel in allChannels)
                {
                    <label class="channel-item">
                        <input type="checkbox"
                               checked="@mutedChannels.Contains(channel)"
                               @onchange="(e) => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                        <span>@channel</span>
                    </label>
                }
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveAsync">Save Preferences</button>
            </div>

            @if (!string.IsNullOrEmpty(statusMessage))
            {
                <div class="alert @(isError ? "alert-danger" : "alert-success") mt-3">@statusMessage</div>
            }
        </div>
    }
</div>

@code {
    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private HashSet<string> mutedChannels = new();
    private bool isLoading = true;
    private string statusMessage = "";
    private bool isError;

    private static readonly string[] allChannels = ["general", "announcements", "engineering", "design", "marketing", "random"];

    protected override async Task OnInitializedAsync()
    {
        isLoading = true;
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        emailNotifications = prefs.EmailNotifications;
        pushNotifications = prefs.PushNotifications;
        weeklyDigest = prefs.WeeklyDigest;
        mutedChannels = new HashSet<string>(prefs.MutedChannels);
        isLoading = false;
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted)
            mutedChannels.Add(channel);
        else
            mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        try
        {
            var prefs = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, mutedChannels.ToList());
            await SettingsService.SaveNotificationPrefsAsync(prefs);
            statusMessage = "Preferences saved successfully!";
            isError = false;
        }
        catch (Exception ex)
        {
            statusMessage = $"Error saving preferences: {ex.Message}";
            isError = true;
        }
    }
}

@namespace sv_6b07da2075794190931c4dd397977f61.Components.Pages.Settings
@using sv_6b07da2075794190931c4dd397977f61.Services
@inject ISettingsService SettingsService

<div class="password-panel">
    <button class="btn btn-outline-secondary expand-toggle" @onclick="() => isExpanded = !isExpanded">
        @(isExpanded ? "▼" : "▶") Change Password
    </button>

    @if (isExpanded)
    {
        <div class="password-form mt-3">
            <div class="form-group">
                <label for="currentPassword">Current Password</label>
                <input id="currentPassword" type="password" class="form-control" @bind="currentPassword" />
            </div>

            <div class="form-group">
                <label for="newPassword">New Password</label>
                <input id="newPassword" type="password" class="form-control" @bind="newPassword" />
            </div>

            <div class="form-group">
                <label for="confirmPassword">Confirm Password</label>
                <input id="confirmPassword" type="password" class="form-control" @bind="confirmPassword" />
            </div>

            <button class="btn btn-warning" @onclick="UpdatePasswordAsync">Update Password</button>

            @if (!string.IsNullOrEmpty(statusMessage))
            {
                <div class="alert @(isError ? "alert-danger" : "alert-success") mt-2">@statusMessage</div>
            }
        </div>
    }
</div>

@code {
    private bool isExpanded;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string statusMessage = "";
    private bool isError;

    private async Task UpdatePasswordAsync()
    {
        statusMessage = "";

        if (string.IsNullOrWhiteSpace(newPassword))
        {
            statusMessage = "New password cannot be empty.";
            isError = true;
            return;
        }

        if (newPassword != confirmPassword)
        {
            statusMessage = "New password and confirmation do not match.";
            isError = true;
            return;
        }

        try
        {
            await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
            statusMessage = "Password updated successfully!";
            isError = false;
            currentPassword = "";
            newPassword = "";
            confirmPassword = "";
        }
        catch (Exception ex)
        {
            statusMessage = $"Error: {ex.Message}";
            isError = true;
        }
    }
}

@namespace sv_6b07da2075794190931c4dd397977f61.Components.Pages.Settings
@using sv_6b07da2075794190931c4dd397977f61.Services

@if (Session is not null)
{
    <div class="modal-backdrop" @onclick="Cancel">
        <div class="modal-dialog" @onclick:stopPropagation="true">
            <div class="modal-content">
                <div class="modal-header">
                    <h5>Revoke Session</h5>
                </div>
                <div class="modal-body">
                    <p>Are you sure you want to revoke the session on <strong>@Session.Device</strong> from <strong>@Session.Location</strong>?</p>
                </div>
                <div class="modal-footer">
                    <button class="btn btn-secondary" @onclick="Cancel">Cancel</button>
                    <button class="btn btn-danger" @onclick="Confirm">Revoke</button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public ActiveSession? Session { get; set; }
    [Parameter] public EventCallback OnConfirmed { get; set; }
    [Parameter] public EventCallback OnCancelled { get; set; }

    private async Task Confirm() => await OnConfirmed.InvokeAsync();
    private async Task Cancel() => await OnCancelled.InvokeAsync();
}

@namespace sv_6b07da2075794190931c4dd397977f61.Components.Pages.Settings
@using sv_6b07da2075794190931c4dd397977f61.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Security Settings</h2>

    @if (isLoading)
    {
        <p class="loading-text">Loading security settings...</p>
    }
    else
    {
        <ChangePasswordPanel />

        <div class="two-factor-section mt-4">
            <h3>Two-Factor Authentication</h3>
            <div class="two-factor-status">
                <span class="status-indicator @(twoFactorEnabled ? "status-enabled" : "status-disabled")">
                    @(twoFactorEnabled ? "● Enabled" : "○ Disabled")
                </span>
                <label class="toggle-label ms-3">
                    <input type="checkbox" @bind="twoFactorEnabled" />
                    <span>@(twoFactorEnabled ? "Disable" : "Enable") 2FA</span>
                </label>
            </div>
            @if (lastPasswordChange.HasValue)
            {
                <p class="text-muted mt-2">Last password change: @lastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }
        </div>

        <div class="sessions-section mt-4">
            <h3>Active Sessions</h3>
            <table class="table sessions-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@session.LastActive.ToString("g")</td>
                            <td>
                                @if (session != sessions.FirstOrDefault())
                                {
                                    <button class="btn btn-sm btn-outline-danger"
                                            @onclick="() => RequestRevoke(session)">
                                        Revoke
                                    </button>
                                }
                                else
                                {
                                    <span class="badge bg-success">Current</span>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>

        <RevokeSessionDialog Session="@sessionToRevoke"
                             OnConfirmed="ConfirmRevokeAsync"
                             OnCancelled="CancelRevoke" />

        @if (!string.IsNullOrEmpty(statusMessage))
        {
            <div class="alert @(isError ? "alert-danger" : "alert-success") mt-3">@statusMessage</div>
        }
    }
</div>

@code {
    private bool isLoading = true;
    private bool twoFactorEnabled;
    private DateTime? lastPasswordChange;
    private List<ActiveSession> sessions = new();
    private ActiveSession? sessionToRevoke;
    private string statusMessage = "";
    private bool isError;

    protected override async Task OnInitializedAsync()
    {
        await LoadSettingsAsync();
    }

    private async Task LoadSettingsAsync()
    {
        isLoading = true;
        var settings = await SettingsService.GetSecuritySettingsAsync();
        twoFactorEnabled = settings.TwoFactorEnabled;
        lastPasswordChange = settings.LastPasswordChange;
        sessions = settings.Sessions;
        isLoading = false;
    }

    private void RequestRevoke(ActiveSession session)
    {
        sessionToRevoke = session;
    }

    private async Task ConfirmRevokeAsync()
    {
        if (sessionToRevoke is null) return;

        try
        {
            await SettingsService.RevokeSessionAsync(sessionToRevoke.Id);
            sessions.Remove(sessionToRevoke);
            statusMessage = $"Session on {sessionToRevoke.Device} revoked.";
            isError = false;
        }
        catch (Exception ex)
        {
            statusMessage = $"Error revoking session: {ex.Message}";
            isError = true;
        }

        sessionToRevoke = null;
    }

    private void CancelRevoke()
    {
        sessionToRevoke = null;
    }
}

