                <h3>Theme</h3>
                <div class="radio-group">
                    @foreach (var t in themes)
                    {
                        <label class="radio-label">
                            <input type="radio" name="theme" value="@t" checked="@(theme == t)"
                                   @onchange="() => theme = t" />
                            <span>@t</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <h3>Font Size</h3>
