@namespace sv_6b07da2075794190931c4dd397977f61.Components.Pages.Settings
@using sv_6b07da2075794190931c4dd397977f61.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Notification Preferences</h2>

    @if (isLoading)
    {
        <p class="loading-text">Loading preferences...</p>
    }
    else
    {
        <div class="notification-form">
            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="emailNotifications" />
                    <span>Email Notifications</span>
                </label>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="pushNotifications" />
                    <span>Push Notifications</span>
                </label>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="weeklyDigest" />
                    <span>Weekly Digest</span>
                </label>
            </div>

            <h3 class="mt-4">Muted Channels</h3>
            <div class="channel-list">
                @foreach (var channel in allChannels)
                {
                    <label class="channel-item">
                        <input type="checkbox"
                               checked="@mutedChannels.Contains(channel)"
                               @onchange="(e) => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                        <span>@channel</span>
                    </label>
                }
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveAsync">Save Preferences</button>
            </div>

            @if (!string.IsNullOrEmpty(statusMessage))
            {
                <div class="alert @(isError ? "alert-danger" : "alert-success") mt-3">@statusMessage</div>
            }
        </div>
    }
</div>

@code {
    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private HashSet<string> mutedChannels = new();
    private bool isLoading = true;
    private string statusMessage = "";
    private bool isError;

    private static readonly string[] allChannels = ["general", "announcements", "engineering", "design", "marketing", "random"];

    protected override async Task OnInitializedAsync()
    {
        isLoading = true;
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        emailNotifications = prefs.EmailNotifications;
        pushNotifications = prefs.PushNotifications;
        weeklyDigest = prefs.WeeklyDigest;
        mutedChannels = new HashSet<string>(prefs.MutedChannels);
        isLoading = false;
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted)
            mutedChannels.Add(channel);
        else
            mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        try
        {
            var prefs = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, mutedChannels.ToList());
            await SettingsService.SaveNotificationPrefsAsync(prefs);
            statusMessage = "Preferences saved successfully!";
            isError = false;
        }
        catch (Exception ex)
        {
            statusMessage = $"Error saving preferences: {ex.Message}";
            isError = true;
        }
    }
}

