@namespace sv_6b07da2075794190931c4dd397977f61.Components.Pages.Settings
@using sv_6b07da2075794190931c4dd397977f61.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Appearance</h2>

    @if (isLoading)
    {
        <p class="loading-text">Loading appearance settings...</p>
    }
    else
    {
        <div class="appearance-form">
            <div class="form-group">
                <h3>Theme</h3>
                <div class="radio-group">
                    @foreach (var t in themes)
                    {
                        <label class="radio-label">
                            <input type="radio" name="theme" value="@t" checked="@(theme == t)"
                                   @onchange="() => theme = t" />
                            <span>@t</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <h3>Font Size</h3>
                <div class="radio-group">
                    @foreach (var fs in fontSizes)
                    {
                        <label class="radio-label">
                            <input type="radio" name="fontSize" value="@fs" checked="@(fontSize == fs)"
                                   @onchange="() => fontSize = fs" />
                            <span>@fs</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" class="form-control" @bind="language">
                    @foreach (var lang in languages)
                    {
                        <option value="@lang">@lang</option>
                    }
                </select>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="compactMode" />
                    <span>Compact Mode</span>
                </label>
            </div>

            <div class="preview-area mt-4">
                <h3>Preview</h3>
                <div class="preview-box @GetPreviewClasses()">
                    <p class="preview-heading">Sample Heading</p>
                    <p class="preview-text">This is how your content will look with the selected settings.</p>
                    <button class="preview-button">Sample Button</button>
                </div>
