toolArgs.file_text:
@page "/settings"
@namespace sv_6b07da2075794190931c4dd397977f61.Components.Pages.Settings
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@activeSection" OnSectionChanged="section => activeSection = section" />

    <main class="settings-content">
        @switch (activeSection)
        {
            case "profile":
                <ProfileSection />
                break;
            case "notifications":
                <NotificationsSection />
                break;
            case "security":
                <SecuritySection />
                break;
            case "appearance":
                <AppearanceSection />
                break;
        }
    </main>
</div>

@code {
    private string activeSection = "profile";
}

.settings-dashboard {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

::deep .settings-sidebar {
    width: 240px;
    background: #f8f9fa;
    border-right: 1px solid #dee2e6;
    padding: 1.5rem 0;
    flex-shrink: 0;
}

::deep .settings-nav {
    list-style: none;
    padding: 0;
    margin: 0;
}

::deep .settings-nav-item {
    display: flex;
    align-items: center;
    padding: 0.75rem 1.5rem;
    cursor: pointer;
    transition: background-color 0.15s, border-left-color 0.15s;
    border-left: 3px solid transparent;
    user-select: none;
}

::deep .settings-nav-item:hover {
    background-color: #e9ecef;
}

::deep .settings-nav-item.active {
    background-color: #e7f1ff;
    border-left-color: #0d6efd;
    font-weight: 600;
}

::deep .settings-nav-icon {
    margin-right: 0.75rem;
    font-size: 1.1rem;
}

::deep .settings-nav-label {
    font-size: 0.95rem;
}

.settings-content {
    flex: 1;
    padding: 2rem;
    max-width: 800px;
}

::deep .settings-section h2 {
    margin-bottom: 1.5rem;
    padding-bottom: 0.75rem;
    border-bottom: 1px solid #dee2e6;
}

::deep .form-group {
    margin-bottom: 1rem;
}

::deep .form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.35rem;
}

::deep .form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 0.375rem;
    font-size: 0.95rem;
}

::deep .form-actions {
    margin-top: 1.5rem;
    display: flex;
    gap: 0.75rem;
}

::deep .btn {
    padding: 0.5rem 1.25rem;
    border-radius: 0.375rem;
    border: 1px solid transparent;
    cursor: pointer;
    font-size: 0.9rem;
    font-weight: 500;
}

::deep .btn-primary {
    background-color: #0d6efd;
    color: white;
}

::deep .btn-primary:hover {
    background-color: #0b5ed7;
}

::deep .btn-secondary {
    background-color: #6c757d;
    color: white;
}

::deep .btn-secondary:hover {
    background-color: #5c636a;
}

::deep .btn-outline-secondary {
    border-color: #6c757d;
    color: #6c757d;
    background: transparent;
}

::deep .btn-outline-danger {
    border-color: #dc3545;
    color: #dc3545;
    background: transparent;
}

::deep .btn-outline-danger:hover {
    background-color: #dc3545;
    color: white;
}

::deep .btn-danger {
    background-color: #dc3545;
    color: white;
}

::deep .btn-warning {
    background-color: #ffc107;
    color: #000;
}

::deep .alert {
    padding: 0.75rem 1rem;
    border-radius: 0.375rem;
    font-size: 0.9rem;
}

::deep .alert-success {
    background-color: #d1e7dd;
    color: #0f5132;
    border: 1px solid #badbcc;
}

::deep .alert-danger {
    background-color: #f8d7da;
    color: #842029;
    border: 1px solid #f5c2c7;
}

/* Profile */
::deep .avatar-preview {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin-bottom: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 0.5rem;
}

::deep .avatar-image {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    object-fit: cover;
    background: #dee2e6;
}

::deep .avatar-url-label {
    font-size: 0.85rem;
    color: #6c757d;
    word-break: break-all;
}

/* Toggles */
::deep .toggle-group {
    margin-bottom: 0.75rem;
}

::deep .toggle-label {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
    font-size: 0.95rem;
}

::deep .toggle-label input[type="checkbox"] {
    width: 1.1rem;
    height: 1.1rem;
}

/* Channels */
::deep .channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    padding: 0.75rem;
    background: #f8f9fa;
    border-radius: 0.375rem;
}

::deep .channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
}

/* Security */
::deep .expand-toggle {
    font-weight: 500;
}

::deep .password-form {
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 0.375rem;
}

::deep .two-factor-status {
    display: flex;
    align-items: center;
}

::deep .status-indicator {
    font-weight: 500;
}

::deep .status-enabled {
    color: #198754;
}

::deep .status-disabled {
    color: #dc3545;
}

::deep .sessions-table {
    width: 100%;
    border-collapse: collapse;
}

::deep .sessions-table th,
::deep .sessions-table td {
    padding: 0.6rem 0.75rem;
    border-bottom: 1px solid #dee2e6;
    text-align: left;
}

::deep .sessions-table thead th {
    font-weight: 600;
    font-size: 0.85rem;
    text-transform: uppercase;
    color: #6c757d;
}

::deep .badge {
    padding: 0.25rem 0.5rem;
    border-radius: 0.25rem;
    font-size: 0.8rem;
}

::deep .bg-success {
    background-color: #198754;
    color: white;
}

/* Modal */
::deep .modal-backdrop {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1050;
}

::deep .modal-dialog {
    background: white;
    border-radius: 0.5rem;
    width: 100%;
    max-width: 440px;
    box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
}

::deep .modal-header {
    padding: 1rem 1.25rem;
    border-bottom: 1px solid #dee2e6;
}

::deep .modal-header h5 {
    margin: 0;
}

::deep .modal-body {
    padding: 1.25rem;
}

::deep .modal-footer {
    padding: 0.75rem 1.25rem;
    border-top: 1px solid #dee2e6;
    display: flex;
    justify-content: flex-end;
    gap: 0.5rem;
}

/* Appearance */
::deep .radio-group {
    display: flex;
    gap: 1.5rem;
    margin-top: 0.5rem;
}

::deep .radio-label {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
}

::deep .preview-area h3 {
    margin-bottom: 0.75rem;
}

::deep .preview-box {
    padding: 1.5rem;
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    transition: all 0.2s;
}

::deep .preview-box.theme-dark {
    background: #1a1a2e;
    color: #e0e0e0;
    border-color: #333;
}

::deep .preview-box.theme-light {
    background: #ffffff;
    color: #212529;
}

::deep .preview-box.theme-system {
    background: #f0f0f0;
    color: #333;
}

::deep .preview-box.font-small {
    font-size: 0.8rem;
}

::deep .preview-box.font-medium {
    font-size: 1rem;
}

::deep .preview-box.font-large {
    font-size: 1.2rem;
}

::deep .preview-box.compact {
    padding: 0.75rem;
    line-height: 1.3;
}

::deep .preview-heading {
    font-weight: 600;
    margin-bottom: 0.5rem;
}

::deep .preview-button {
    margin-top: 0.75rem;
    padding: 0.4rem 1rem;
    border-radius: 0.3rem;
    border: 1px solid currentColor;
    background: transparent;
    color: inherit;
    cursor: pointer;
}

::deep .loading-text {
    color: #6c757d;
    font-style: italic;
}

::deep .mt-2 { margin-top: 0.5rem; }
::deep .mt-3 { margin-top: 1rem; }
::deep .mt-4 { margin-top: 1.5rem; }
::deep .ms-3 { margin-left: 1rem; }
::deep .text-muted { color: #6c757d; }

